'use strict';

function isBoundary(text, i) {
  const prev = text[i - 1];
  if (/[\s\-_/.]/.test(prev)) return true;
  return /[a-z]/.test(prev) && /[A-Z]/.test(text[i]);
}

module.exports = { isBoundary };

